<template>
  <div class="exhibition-page">
    <section class="page-heading"><div><p class="eyebrow">CURATED EXHIBITIONS</p><h1>专题展览</h1><p>从摄影作品流中挑选主题，用策展的方式重新发现光影。</p></div><a-button @click="router.push('/community')">浏览作品社区</a-button></section>
    <div class="filter-bar"><a-input-search v-model:value="searchText" placeholder="搜索展览主题" enter-button="搜索" @search="load" /><a-button @click="load">刷新</a-button></div>
    <a-alert v-if="error" type="warning" show-icon message="展览暂时无法加载" description="请确认后端服务已启动，或稍后再次刷新。" closable @close="error=false" />
    <a-spin :spinning="loading"><div class="exhibition-grid"><article v-for="item in exhibitions" :key="item.id" class="exhibition-card" @click="router.push('/exhibitions/' + item.id)"><div class="cover"><img v-if="item.coverUrl" :src="item.coverUrl" :alt="item.title" /><div v-else class="cover-placeholder"><PictureOutlined /><span>{{ item.theme || '摄影主题' }}</span></div><span class="count">{{ item.pictureCount || 0 }} 件展品</span></div><div class="card-body"><p class="theme">{{ item.theme || '主题展览' }}</p><h2>{{ item.title }}</h2><p>{{ item.description || '用一组作品讲述一个摄影主题。' }}</p><div><span>{{ formatDate(item.startTime) }}{{ item.endTime ? ` - ${formatDate(item.endTime)}` : '' }}</span><span><EyeOutlined /> {{ item.viewCount || 0 }}</span></div></div></article></div><a-empty v-if="!loading && !exhibitions.length" description="还没有已发布的专题展览"><template #image><PictureOutlined /></template><p>专题展览由管理员策划发布，敬请期待。</p></a-empty></a-spin>
    <a-pagination v-if="total > pageSize" v-model:current="current" :page-size="pageSize" :total="total" @change="load" />
    <a-modal v-model:open="detailOpen" :title="detail?.title" :footer="null" width="820px"><a-spin :spinning="detailLoading"><div v-if="detail" class="detail-view"><p class="theme">{{ detail.theme || '主题展览' }}</p><p>{{ detail.description }}</p><div class="detail-grid"><a v-for="picture in detailPictures" :key="picture.id" :href="`/picture/${picture.pictureId}`" target="_blank"><img :src="picture.thumbnailUrl || picture.url" :alt="picture.caption || '展览作品'" /><span>{{ picture.caption || '查看作品' }}</span></a></div><div v-if="detailWorks.length" class="work-list"><strong>关联作品</strong><span v-for="work in detailWorks" :key="work.id">{{ work.caption || `作品 #${work.workId}` }}</span></div></div></a-spin></a-modal>
  </div>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { message } from 'ant-design-vue'; import { EyeOutlined, PictureOutlined } from '@ant-design/icons-vue'; import { useRouter } from 'vue-router'; import { getExhibition, listExhibitionPictures, listExhibitionWorks, listExhibitions } from '@/api/photoCommunity'; import { getPictureVoByIdUsingGet } from '@/api/pictureController'
const router=useRouter();const current=ref(1);const pageSize=ref(12);const total=ref(0);const searchText=ref('');const exhibitions=ref<any[]>([]);const loading=ref(false);const error=ref(false);const detailOpen=ref(false);const detailLoading=ref(false);const detail=ref<any>();const detailPictures=ref<any[]>([]);const detailWorks=ref<any[]>([])
function formatDate(value:any){if(!value)return '长期展出';const date=new Date(value);return Number.isNaN(date.getTime())?'长期展出':date.toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'})}
async function load(){loading.value=true;error.value=false;try{const res:any=await listExhibitions({current:current.value,pageSize:pageSize.value,searchText:searchText.value||undefined});if(res.data.code===0){exhibitions.value=res.data.data?.records||[];total.value=Number(res.data.data?.total||0)}else error.value=true}catch{error.value=true}finally{loading.value=false}}
async function openExhibition(item:any){detailOpen.value=true;detailLoading.value=true;detail.value=undefined;detailPictures.value=[];detailWorks.value=[];try{const [info,pictures,works]:any[]=await Promise.all([getExhibition(item.id),listExhibitionPictures(item.id),listExhibitionWorks(item.id)]);if(info.data.code===0)detail.value=info.data.data;if(pictures.data.code===0){const relations=pictures.data.data||[];detailPictures.value=await Promise.all(relations.map(async(relation:any)=>{try{const pictureRes:any=await getPictureVoByIdUsingGet({id:relation.pictureId});return {...relation,...(pictureRes.data.code===0?pictureRes.data.data:{})}}catch{return relation}}))}if(works.data.code===0)detailWorks.value=works.data.data||[]}catch{message.error('展览详情加载失败')}finally{detailLoading.value=false}}
onMounted(load)
</script>
<style scoped>
.exhibition-page{max-width:1200px;margin:0 auto}.page-heading{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:26px}.eyebrow{margin:0 0 10px;color:#668473;font-size:11px;font-weight:600;letter-spacing:2px}.page-heading h1{margin:0 0 8px;color:#20322e;font-size:38px}.page-heading p:not(.eyebrow){margin:0;color:#748078;line-height:1.7}.filter-bar{display:flex;gap:12px;max-width:700px;margin-bottom:20px}.filter-bar .ant-input-search{max-width:500px}.exhibition-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:22px}.exhibition-card{overflow:hidden;background:#fff;border:1px solid #e1e9e2;border-radius:8px;cursor:pointer;transition:.2s}.exhibition-card:hover{transform:translateY(-3px);box-shadow:0 12px 25px rgba(35,67,48,.08)}.cover{position:relative;height:190px;background:#eaf1eb}.cover img{width:100%;height:100%;object-fit:cover}.cover-placeholder{display:grid;place-items:center;align-content:center;gap:8px;height:100%;color:#5f8069;font-size:30px;background:linear-gradient(135deg,#eaf3eb,#d8e8dc)}.cover-placeholder span{font-size:14px}.count{position:absolute;right:12px;bottom:12px;padding:4px 8px;background:rgba(255,255,255,.9);border-radius:4px;color:#486451;font-size:11px}.card-body{padding:16px}.theme,.detail-view .theme{margin:0 0 6px;color:#6d9b79;font-size:12px}.card-body h2{margin:0 0 8px;color:#304c3a;font-size:19px}.card-body p:not(.theme){height:40px;margin:0 0 14px;color:#748078;font-size:13px;line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.card-body>div:last-child{display:flex;justify-content:space-between;color:#9aa59e;font-size:11px}.exhibition-page>.ant-pagination{margin-top:26px;text-align:right}.detail-view>p:not(.theme){color:#748078;line-height:1.7}.detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:18px}.detail-grid a{position:relative;height:130px;overflow:hidden;border-radius:5px}.detail-grid img{width:100%;height:100%;object-fit:cover}.detail-grid span{position:absolute;right:0;bottom:0;left:0;padding:5px;background:rgba(0,0,0,.5);color:#fff;font-size:11px}.work-list{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px;color:#6b7b71;font-size:12px}.work-list strong{color:#355443}@media(max-width:850px){.exhibition-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.page-heading{display:block}.page-heading .ant-btn{margin-top:14px}.filter-bar{display:block}.filter-bar .ant-input-search{max-width:none;margin-bottom:10px}.exhibition-grid{grid-template-columns:1fr}.detail-grid{grid-template-columns:repeat(2,1fr)}}
</style>
